export function searchIcons(query="",category="all"){const q=query.normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim().split(/\s+/).filter(t=>t&&!["the","our","on","a","to","your","us","my","at","and"].includes(t));return CATALOGUE.filter(i=>(category==="all"||i.category===category)&&q.every(t=>[i.id,i.name,CATEGORIES.find(c=>c.id===i.category)?.name,...i.synonyms].join(" ").toLowerCase().includes(t)));}
